// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _deposit, uint256 _withdraw) public {
        vm.assume(_deposit > 0 && _deposit <= 10**18);
        vm.assume(_withdraw > 0 && _withdraw <= _deposit);
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit
        vm.deal(address(this), _deposit);
        c.Deposit{value: _deposit}();
        uint256 balanceBefore = c.balances(address(this));
        vm.assume(balanceBefore == _deposit);

        // Collect
        c.Collect(_withdraw);
        uint256 balanceAfter = c.balances(address(this));

        // General rule: balance decreases by exactly _withdraw
        assertTrue(balanceAfter == balanceBefore - _withdraw);
    }
}

