pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= c.balances(caller) + depositAmount);
        vm.assume(collectAmount <= depositAmount);

        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Record balance sum before deposit
        uint256 sumBeforeDeposit = 0;

        // Deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance sum after deposit
        uint256 sumAfterDeposit = 0;

        // Attempt collect (may revert internally)
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After collect, check the rule
        if (success) {
            // Total balance sum should not increase beyond the original deposit
            uint256 sumAfterCollect = 0;
            // We cannot iterate all addresses, but we can check the caller's balance is not increased
            // Rule: caller's balance after collect <= caller's balance after deposit
            assertTrue(c.balances(caller) <= sumAfterDeposit, "Balance should not increase");
        } else {
            // If collect reverted, balances unchanged
            assertTrue(c.balances(caller) == sumAfterDeposit, "Balance unchanged after revert");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Ensure valid amounts; bound to avoid overflow in reference
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount <= type(uint256).max / 2);

        // Set up: initialize and set MinSum to 0 so Collect can succeed
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Now call Collect; if depositAmount >= collectAmount it should succeed
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // General rule: after any sequence, the caller's balance must be >= 0 (i.e., uint256)
        // Since balances are uint256, they are never negative; but this rule would fail if
        // an underflow occurs (which would revert in reference, but in mutated version the
        // balance increases, no underflow). Actually, we need a rule that distinguishes.
        // Instead: after Collect, balances[caller] should be <= original deposited amount.
        // In reference: balances[caller] = depositAmount - collectAmount (if collectAmount <= depositAmount, else unchanged).
        // In mutant: balances[caller] = depositAmount + collectAmount (if collect triggered), always > depositAmount.
        // So rule: balances[caller] <= depositAmount (if Collect succeeded) OR if call reverted, balances unchanged (== depositAmount).
        // Simpler: if Collect succeeded, then balances[caller] should not increase.
        uint256 balanceAfter = c.balances(caller);
        if (success) {
            assertTrue(balanceAfter <= depositAmount, "Balance increased after Collect");
        } else {
            // If revert, balance unchanged
            assertTrue(balanceAfter == depositAmount, "Balance changed after revert");
        }
    }
}

