pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmt, uint256 collectAmt) public {
        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit funds from caller
        vm.deal(address(c), 0);
        vm.deal(address(this), 0);
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Capture balances before Collect
        uint256 balanceCallerBefore = caller.balance;
        uint256 balanceContractBefore = address(c).balance;

        // Bound collectAmt to avoid arithmetic overflows in reference
        collectAmt = bound(collectAmt, 0, c.balances(caller));

        // Attempt Collect
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // Rule: If Collect did not revert, then (caller.balance + contract.balance) is unchanged
        if (ok) {
            uint256 balanceCallerAfter = caller.balance;
            uint256 balanceContractAfter = address(c).balance;
            assertTrue(
                balanceCallerBefore + balanceContractBefore == balanceCallerAfter + balanceContractAfter,
                "Sum of caller and contract balance changed after Collect"
            );
        } else {
            assertTrue(true); // revert case passes vacuously
        }
    }
}

