pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 minSum, uint256 amount) public {
        // Bound inputs to avoid overflow; amount should not exceed initialBalance for meaningful test
        vm.assume(initialBalance > 0);
        vm.assume(amount <= initialBalance);
        vm.assume(initialBalance <= type(uint128).max);

        // Initialize contract: set MinSum and fund the caller
        vm.prank(address(this));
        c.SetMinSum(minSum);
        vm.prank(address(this));
        c.SetLogFile(address(0)); // dummy log address to avoid revert on Log.AddMessage
        vm.prank(address(this));
        c.Initialized();

        // Fund caller by depositing initialBalance
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record total ether held by contract and sum of all balances before Collect
        uint256 contractBalanceBefore = address(c).balance;
        // Compute sum of all balances (assuming only caller has non-zero balance for simplicity)
        uint256 callerBalanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

        // After Collect, compute new balances and contract balance
        uint256 contractBalanceAfter = address(c).balance;
        uint256 callerBalanceAfter = c.balances(caller);

        // General rule: if Collect succeeded, the total (contract balance + sum of balances) remains unchanged
        if (success) {
            uint256 totalBefore = contractBalanceBefore + callerBalanceBefore;
            uint256 totalAfter = contractBalanceAfter + callerBalanceAfter;
            assertTrue(totalBefore == totalAfter, "Total value should be preserved");
        }
    }
}

