pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint minSum, uint depositAmount, uint collectAmount) public {
        // Bound parameters to reasonable ranges
        vm.assume(minSum > 0 && minSum <= 1e24);
        vm.assume(depositAmount >= minSum && depositAmount <= 1e24);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Initialize and set MinSum
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit funds
        vm.deal(address(this), depositAmount);
        c.Deposit{value: depositAmount}();

        // Call Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: if Collect succeeded, sender's balance should be less than MinSum
        // For the reference contract, a successful Collect requires balance >= MinSum initially,
        // and after subtraction the balance could be >= MinSum or < MinSum.
        // But the buggy version removes the MinSum check, so after a successful Collect
        // the balance can be > 0 even if it was < MinSum initially.
        // The invariant is: after any successful Collect, the final balance is either 0 or exactly (depositAmount - collectAmount).
        // A more general property: the sender's balance after Collect is always <= depositAmount - collectAmount
        // and equals that if Collect succeeded.
        // We'll assert: if Collect succeeded, then c.balances(address(this)) == depositAmount - collectAmount.
        if (success) {
            assertTrue(c.balances(address(this)) == depositAmount - collectAmount);
        } else {
            assertTrue(c.balances(address(this)) == depositAmount);
        }
    }
}

