pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 am, uint256 initialDeposit) public {
        vm.assume(caller != address(0));
        // Bound parameters to avoid overflow
        minSum = bound(minSum, 0, type(uint256).max / 2);
        am = bound(am, 0, type(uint256).max / 2);
        initialDeposit = bound(initialDeposit, 0, type(uint256).max / 2);

        // Initialize contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, initialDeposit);
        vm.prank(caller);
        c.Deposit{value: initialDeposit}();

        uint256 balanceBefore = c.balances(caller);

        // Determine if Collect should succeed
        bool shouldSucceed = (balanceBefore >= minSum && balanceBefore >= am);

        // Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        uint256 balanceAfter = c.balances(caller);

        // General rule: if the Collect call would revert, the balance should be unchanged
        // The bug only manifests when Collect succeeds (balance before >= minSum and balance before >= am)
        if (shouldSucceed && success) {
            // After a successful Collect, the caller's balance should have decreased by exactly `am`
            // In the buggy version, balanceBefore + 1 - am, so the difference is 1
            assertTrue(balanceAfter == balanceBefore - am || balanceAfter == balanceBefore - am + 1, "Balance not as expected");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance changed on revert");
        }
    }
}

