import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 logAddr, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        logAddr = bound(logAddr, 1, type(uint160).max);
        vm.deal(sender, depositAmount);

        c.SetMinSum(minSum);
        c.SetLogFile(address(uint160(logAddr)));
        c.Initialized();

        address logBefore = address(c.Log());

        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        vm.prank(sender);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        address logAfter = address(c.Log());
        assertTrue(logBefore == logAfter);
    }
}

