pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 _minSum, uint256 _depositValue) public {
        // Restrict inputs to valid ranges
        vm.assume(_am > 0 && _am <= 1e36);
        vm.assume(_minSum >= 0 && _minSum <= 1e36);
        vm.assume(_depositValue >= 0 && _depositValue <= 1e36);

        // Set up initial state: MinSum, LogFile, initialize
        c.SetMinSum(_minSum);
        address logAddr = address(1); // arbitrary
        c.SetLogFile(logAddr);
        c.Initialized();

        // Deposit some ether to the contract
        vm.deal(address(this), _depositValue);
        c.Deposit{value: _depositValue}();

        // Record Log before Collect
        address logBefore = address(c.Log());

        // Call Collect
        c.Collect(_am);

