import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 am, uint256 deposit, bool initLog) public {
        // Restrict inputs to avoid overflow/underflow
        vm.assume(deposit > 0 && deposit <= type(uint128).max);
        vm.assume(am <= deposit);
        vm.assume(minSum <= type(uint128).max);

        // Setup
        c.SetMinSum(minSum);
        c.Initialized();

        address user = address(0x1234);
        vm.deal(user, deposit);
        vm.prank(user);
        c.Deposit{value: deposit}();

        // Attempt to call Collect - may revert due to insufficient balance or minSum condition
        uint256 bal = c.balances(user);
        bool expectedRevert = bal < minSum || bal < am;

        // if initLog is true, set a valid log file; otherwise leave it unset (which will cause bug to surface)
        if (initLog) {
            vm.prank(address(0xdead));
            c.SetLogFile(address(0xdeadbeef));
        }

        vm.prank(user);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // General rule: Collect should revert exactly when expectedRevert is true
        // The bug (inserted require) causes an extra revert in SetLogFile, but that cannot affect
        // the Collect call's revert behavior because SetLogFile is never called within Collect.
        // So success indicator depends only on expectedRevert.
        assertTrue(success != expectedRevert);
    }
}

