pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 amount) public {
        // Precondition: reference contract needs initialized and SetLogFile set
        c.SetMinSum(minSum);
        // Initialize the contract
        c.Initialized();
        // Set the LogFile to a dummy address (can be zero address, doesn't matter)
        c.SetLogFile(address(0xdead));

        // Record the LogFile address before calling Collect
        address logBefore = address(0);
        // Use low-level call to read the public getter since it's an external contract address
        // The getter is `Log()` returns the address of the LogFile contract
        {
            (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("Log()"));
            require(success);
            logBefore = abi.decode(data, (address));
        }

        // Ensure caller has enough balance
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);

        // Perform deposit to increase balance
        vm.prank(caller);
        c.Deposit{value: 1 ether}();

        // Now call Collect
        vm.prank(caller);
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));

        // After the call, verify that LogFile address has not changed
        {
            (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("Log()"));
            require(success);
            address logAfter = abi.decode(data, (address));
            assertTrue(logBefore == logAfter, "SetLogFile must not change after Collect");
        }
    }
}

