pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 am) public {
        vm.assume(caller != address(0));
        vm.assume(minSum <= type(uint256).max);
        vm.assume(am <= type(uint256).max);

        // Set MinSum to some value
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller
        vm.deal(caller, am);
        vm.prank(caller);
        c.Deposit{value: am}();

        // Ensure caller has enough balance
        vm.assume(c.balances(caller) >= am);

        // Capture SetLogFile address before Collect
        address logBefore = address(c.LogFile());

        // Call Collect
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        if (success) {
            // If Collect succeeded, LogFile address should remain unchanged
            assertTrue(address(c.LogFile()) == logBefore);
        } else {
            // If it reverted, still check LogFile didn't change
            assertTrue(address(c.LogFile()) == logBefore);
        }
    }
}
